const section=(heading,paragraphs=[],bullets=[])=>({heading,paragraphs,bullets});
const article=(id,title,summary,sections)=>({id,title,summary,tags:'component settings thermal gate '+title,sections});
const FIELDS={
 'cand.series':'component-series','cand.parallel':'component-parallel','cand.totalCount':'component-total','inst.currentPolarity':'component-orientation',
 'cand.gateType':'component-gate-waveform','cand.vgsOn':'component-vgs-on','cand.vgsOff':'component-vgs-off','cand.gateOn':'component-analog-on','cand.gateOff':'component-analog-off',
 'cand.rgOn':'component-rg-on','cand.rgOff':'component-rg-off','cand.thermal.mode':'component-temperature-model','cand.thermal.temperature':'component-temperature',
 'cand.thermal.Rth':'component-rth','cand.thermal.scope':'component-rth-scope','cand.thermal.maxTemperature':'component-temperature-limit'
};
export const componentTopic=path=>FIELDS[path]||null;
export const COMPONENT_ARTICLES=[
 article('component-series','Devices in series','Number of devices sharing the mapped bank voltage.',[
  section('How it is used',['Per-device voltage = mapped voltage / devices in series. Every series device carries the same branch current. Enter a positive whole number. Example: two devices across a mapped 800 V bank are each evaluated at 400 V, assuming ideal sharing.']),
  section('Effect on losses',['The lower per-device voltage can change voltage-dependent switching-energy queries and core flux from mapped inductor voltage. Total physical device count separately scales per-device loss to the whole bank. Series count alone does not automatically update total count.'])]),
 article('component-parallel','Devices in parallel','Number of parallel branches sharing the mapped bank current.',[
  section('How it is used',['Per-device current = mapped current × current orientation / devices in parallel. Enter a positive whole number. Example: a 20 A bank with two parallel devices is evaluated at 10 A per device, assuming ideal sharing.']),
  section('Effect on losses',['Current-dependent drops, resistance and event energies are evaluated at that per-device current. At a constant 20 mΩ, each 10 A device dissipates 2 W and a two-device bank dissipates 4 W. Enter the matching total physical device count separately.'])]),
 article('component-total','Total physical device count','Number of physical devices represented by this component bank.',[
  section('How it is used',['Bank loss = per-device loss × total physical device count. Normally total count = series count × parallel count. For two series devices in each of three parallel branches, enter 6. Current and voltage sharing are set by parallel and series counts, not by total count.']),
  section('Replicated banks',['A different total count requires the Additional replicated banks confirmation. Use it only for additional identical banks represented by the same per-device conditions. The total count also affects iterative temperature when Rth represents the entire bank.'])]),
 article('component-orientation','Current orientation','Align the imported component current with the model’s positive direction.',[
  section('Choose +1 or −1',['+1 retains the imported sign; −1 reverses it before the current is divided between parallel devices. MOSFET current is drain-to-source positive. Diode current is forward positive. Check the source waveform’s measurement direction.']),
  section('Effect on losses',['MOSFET gate-on current uses the channel model in either direction; negative current with the gate off uses the enabled body path. A diode’s forward loss uses positive current. Reversing orientation can therefore change conduction masks and recovery events. It does not change the converter power-pair polarity or stored waveform.'])]),
 article('component-gate-waveform','Gate waveform','Tell the tool whether the mapped gate signal is logic or actual gate voltage.',[
  section('Logic',['Choose logic for a 0/1 command. A sample above 0.5 is ON; other samples are OFF. Logic on Vgs and Logic off Vgs supply the physical gate voltages used for characteristic queries. Changes of state identify switching events.']),
  section('Analog',['Choose analog for a gate-to-source voltage trace in volts. ON/OFF thresholds classify the state with hysteresis; between thresholds, the previous state is retained. The actual sample voltage is used as Vgs for characteristic queries. These thresholds classify imported data; they do not model a transistor’s physical turn-on transient.'])]),
 ...['on','off'].map(state=>article(`component-vgs-${state}`,`Logic ${state} Vgs [V]`,`Physical gate-to-source voltage assigned to logic-${state==='on'?'ON':'OFF'} samples.`,[
  section('When it is used',[`This setting applies when Gate waveform is logic. Enter the actual driver ${state==='on'?'high':'low'} voltage in volts; for example, ${state==='on'?'15 V':'0 V or a negative turn-off voltage such as −3 V, where applicable'}. The 0/1 command determines the switching state; this field supplies Vgs to device-curve queries for ${state==='on'?'ON':'OFF'} samples.`]),
  section('Effect on calculations',[`Changing this value can change losses when an active characteristic depends on Vgs at the queried ${state==='on'?'ON':'OFF'} samples. It does not change the command duty cycle, event count or imported waveform. Fixed-reference or Vgs-independent curves do not acquire a new gate-voltage model from this setting.`])])),
 ...['on','off'].map(state=>article(`component-analog-${state}`,`Analog ${state.toUpperCase()} threshold [V]`,`Gate-voltage threshold used to classify the ${state.toUpperCase()} state.`,[
  section('State detection',[`For an analog waveform, the gate becomes ${state==='on'?'ON at or above this threshold':'OFF at or below this threshold'}. The ON threshold must exceed the OFF threshold. Between them, the previous state is retained. State transitions identify switching events and select channel/body conduction masks. The measured analog sample, rather than this threshold, supplies Vgs to curves.`])])),
 ...['on','off'].map(state=>article(`component-rg-${state}`,`Rg turn-${state} [Ω]`,`Gate resistance used for the enabled turn-${state} energy model.`,[
  section('Which value to enter',[`Enter the nonnegative resistance in ohms matching the Rg convention of your ${state==='on'?'Eon':'Eoff'} characteristic. Check whether the datasheet reference includes external resistance only or another defined total; use the same convention.`]),
  section('Effect on switching losses',[`At detected turn-${state} events, this value is passed as the Rg dependency to the ${state==='on'?'Eon':'Eoff'} query. Event energies are summed and divided by the analysis duration. It does not alter imported switching edges. If the enabled curve has no varying Rg data, changing Rg cannot create an inferred resistance dependence.`])])),
 article('component-temperature-model','Temperature model','Choose a prescribed temperature or an iterated steady-state estimate.',[
  section('Fixed',['The tool evaluates enabled losses at Device temperature. It does not calculate a temperature rise from Rth in this mode. Choose this for a known measured temperature or a controlled comparison at the same device temperature.']),
  section('Iterative',['The tool starts at the ambient/reference temperature, calculates loss, estimates a new temperature from T = Treference + loss × Rth, then repeats with temperature-dependent curves. The solver is damped and checks convergence and the temperature limit. Each candidate has an independent thermal model.'])]),
 article('component-temperature','Device or ambient/reference temperature [°C]','The meaning of this field follows the selected temperature model.',[
  section('Fixed model',['This is the prescribed device temperature used to query temperature-dependent characteristics. Example: enter 100 °C to compare device losses at 100 °C. Rth does not add a temperature rise.']),
  section('Iterative model',['This is the ambient, case or other reference temperature at the cold end of the thermal resistance you supply. Match the temperature reference to the Rth definition: for example, a case temperature with a junction-to-case resistance. Tdevice = Treference + the selected device/bank loss × Rth.'])]),
 article('component-rth','Thermal resistance [K/W]','Temperature rise per watt between the device/bank and the chosen reference.',[
  section('How it is used',['In iterative mode, temperature rise = selected loss × Rth. For 10 W and 2 K/W, the rise is 20 K; a 40 °C reference gives 60 °C. The loss comes from one device or the whole bank according to Rth represents. Enter zero or a positive value.']),
  section('Choose a matching thermal path',['Use an effective resistance whose endpoints match the reference and target temperatures. Junction-to-case resistance alone is not a junction-to-ambient path. A higher Rth normally raises the estimated temperature, which can change temperature-dependent losses. This field is not used for temperature rise in fixed mode.'])]),
 article('component-rth-scope','Rth represents: device or bank','Choose which loss is multiplied by the thermal resistance.',[
  section('Device',['Use device when Rth applies to one physical device. The solver uses that device’s loss. Example: four devices at 2 W each and 3 K/W per device give a 6 K rise for each device.']),
  section('Bank',['Use bank when your effective Rth applies to the entire configured bank. The solver uses per-device loss × total physical device count. Four devices at 2 W each and a bank Rth of 3 K/W give a 24 K rise. Choose this only if that effective bank model matches your thermal arrangement; coupling between separate component instances is not solved.'])]),
 article('component-temperature-limit','Maximum permitted temperature [°C]','Upper temperature bound for the iterative thermal calculation.',[
  section('When it is checked',['In iterative mode, a trial target above this limit causes the calculation to fail rather than reporting a converged temperature. Set a positive value above the ambient/reference temperature and appropriate to your study. A target equal to the limit is not rejected for exceeding it.']),
  section('What it does',['The limit does not clamp temperature or reduce losses. A failure retains diagnostic trial history for review. This limit is not an additional fixed-mode temperature check, and it does not perform device-rating validation.'])])
];
